def solve(g):
    H=len(g); W=len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=max(cnt,key=lambda k:cnt[k])
    cells=[(i,j,v) for i in range(H) for j in range(W) if g[i][j]!=bg]
    # frame blocks: colors forming runs of >=2 aligned cells
    from collections import defaultdict
    bycolor=defaultdict(list)
    for i,j,v in cells: bycolor[v].append((i,j))
    blocks=[]  # (color, cells_set, rows, cols)
    for v,ps in bycolor.items():
        if len(ps)<2: continue
        rs={i for i,j in ps}; cs={j for i,j in ps}
        if len(ps)==len(rs) and len(rs)==len(cs) and len(ps)>=2:  # line
            pass
        blocks.append((v,set(ps),min(rs),max(rs),min(cs),max(cs)))
    # marker cells: isolated single cells
    markers=[(i,j,v) for i,j,v in cells if sum(1 for di,dj in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+di<H and 0<=j+dj<W and g[i+di][j+dj]==v)==0]
    out=[[bg]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in set(it:=[(a,b) for _,a,b in markers]): out[i][j]=4
    # place frame blocks unchanged
    for v,cs_,r0,r1,c0,c1 in blocks:
        if len(cs_)>=2:
            for i in range(r0,r1+1):
                for j in range(c0,c1+1):
                    if (i,j) in cs_: out[i][j]=v
    # for each marker: determine strip axis (horizontal if frame blocks vertical, vertical otherwise)
    # assume horizontal strips here (blocks are vertical lines): toward block whose row-range contains marker row
    for (mi,mj,v) in markers:
        # strip from marker toward containing block, exclusive of wall
        cands=[b for b in blocks if b[0]!=v and len(b[2])>=1 and (b[2]<=mi<=b[3])]
        if len(cands)==1:
            tgt=cands[0]
