                src_lo,src_hi=lo,hi
                a=min(src_lo,src_hi)
                b=max(src_lo,src_hi)
                for j in range(min(a,mj)+ (0 if mj<a else 1), max(b,mj)):
                    if g[mi][j]==bg: out[mi][j]=v
        else:
            # toward farthest block
            best=max(blocks,key=lambda b:abs((b[2]+b[3])/2-mi))
            lo,hi=best[2],best[3]
            a=min(lo,hi); b=max(lo,hi)
            for j in range(min(a,mj)+1, max(b,mj)):
                if g[mi][j]==bg: out[mi][j]=v
        # opposite strip at scaled offset
        own=tgt[4]-tgt[5] if False else None
    return out
