def solve2(g):
    H=len(g); W=len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=max(cnt,key=lambda k:cnt[k])
    cells=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j]!=bg]
    bycolor={}
    for i,j,v in cells: bycolor.setdefault(v,[]).append((i,j))
    blocks=[]
    for v,ps in bycolor.items():
        rs={i for i,j in ps}; cs={j for i,j in ps}
        if len(ps)>=2 and len(ps)==len(rs)==len(cs):
            blocks.append((v,set(ps),min(rs),max(rs),min(cs),max(cs)))
    markers=[(i,j,v) for i,j,v in cells if sum(1 for di,dj in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+di<H and 0<=j+dj<W and g[i+di][j+dj]==v)==0]
    out=[[bg]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg: out[i][j]=4
    for v,cs_,r0,r1,c0,c1 in blocks:
        for i in range(r0,r1+1):
            for j in range(c0,c1+1):
                if (i,j) in cs_: out[i][j]=v
    def dist(m,b):
        return max(abs(m[0]-b[0]),abs(m[1]-b[1]))
    for (mi,mj,v) in markers:
        contain=[b for b in blocks if b[0]!=v and b[2]<=mi<=b[3]]
        if contain:
            tgt=max(contain,key=lambda b:b[3]-b[2])  # containing block
        else:
            tgt=max(blocks,key=lambda b:dist((mi,mj),b))
        # horizontal strip from marker toward tgt
        a=min(tgt[2],tgt[3]); b=max(tgt[2],tgt[3])
        for j in range(min(a,mj)+1, max(b,mj)):
            if g[mi][j]==bg: out[mi][j]=v
        # opposite strip: scale offset round(o * oppsize/ownsize)
        own=tgt[4]-tgt[5]+1; opp=sum(1 for bb in blocks if bb[0]!=tgt[0] and len(bb[2])==1)
        o=mi-tgt[2]
        for bb in blocks:
            if bb[0]==tgt[0]: continue
            if len(bb[2])!=1: continue
            o2=round(o*len(bb[2])/own)
            if 0<=o2<len(bb[2]):
                ri=bb[2]+o2
                lo2,hi2=bb[4],bb[5]
                for j in range(lo2+1, hi2):
                    if g[ri][j]==bg: out[ri][j]=v
    return out
